/* Qwen returning-fan leg readability only. Same geometry, physics untouched. */
(()=>{const role=window.ArenaCharacterModules.qwen,previous=role.drawShot;role.drawShot=function(c,p,env){if(p.characterId!=='qwen'||p.visual!=='returning-fan')return previous.call(this,c,p,env);const inbound=p.returned===true,t=p.age??env.elapsed;function fan(x,y,r,a){c.save();c.translate(x,y);c.rotate(a);c.fillStyle=inbound?'rgba(255,210,136,.32)':'rgba(168,151,255,.32)';c.strokeStyle=inbound?'#ffe3ad':'#f2e5ff';c.lineWidth=1.2;c.beginPath();c.moveTo(0,0);c.arc(0,0,r,-2.75,-.40);c.closePath();c.fill();c.stroke();for(let j=0;j<8;j++){let v=-2.75+j*2.35/7;c.beginPath();c.moveTo(0,0);c.lineTo(r*Math.cos(v),r*Math.sin(v));c.stroke();}c.restore();}c.save();c.translate(p.x,p.y);c.scale(p.dir||1,1);for(let j=3;j>0;j--){c.globalAlpha=.07*j;fan(-j*10,0,22,t*18-j*.25);}c.globalAlpha=1;fan(0,0,p.ultimate?34:24,t*18);c.restore();return true;};})();
